class SiteResetRunnerTemplate(SiteResetCommons):

    def __init__(self, **kwargs):
        super(SiteResetRunnerTemplate, self).__init__(operation_description='Site Reset',
                                                      kpi_names=['kpi1a', 'kpi1b', 'kpi1c'],
                                                      **kwargs)
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 1.5 * 60
        self.delay_for_checking_allowed_alarms = self.delay_for_checking_allowed_alarms or 15

    def run_operation(self):
        self.custom_logger(log_info_to_console, msg="BTS Site reset", log_hierarchy=2)
        convert_to_robot_kw(self.bbu.reset_bts, bts_id=self.bts_id, du_id=self.du_id)


class PowerResetRunnerTemplate(SiteResetCommons):

    def __init__(self, **kwargs):
        super(PowerResetRunnerTemplate, self).__init__(operation_description='Power Site Reset', kpi_names=['kpi3'],
                                                       **kwargs)

        self._confirmation_delay = 5
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 2 * 60
        self._kpi_params['kpi3'] = {}

    def run_operation(self):
        self.custom_logger(log_info_to_console, msg="BTS Power OFF", log_hierarchy=2)
        convert_to_robot_kw(self.bbu.bts_power_off, bts_id=self.bts_id, du_id=self.du_id,
                            confirmation_delay=self._confirmation_delay)
        is_pingable = convert_to_robot_kw(self.bbu.mplane_is_pingable_from_ws, bts_id=self.bts_id, du_id=self.du_id)
        if is_pingable:
            raise Exception("BTS is still pingable after power off. Perhaps you have wrong defined PDU port to BTS"
                            "(or even PDU address) in configuration init.py")
        convert_to_robot_kw(self.bbu.bts_power_on, bts_id=self.bts_id, du_id=self.du_id,
                            confirmation_delay=self._confirmation_delay)
        self.custom_logger(log_info_to_console, msg="BTS Power ON", log_hierarchy=2)
        bts_power_on_timestamp = datetime.datetime.now(pytz.utc) - datetime.timedelta(seconds=self._confirmation_delay)
        self.custom_logger(log_info_to_console, msg="BTS Power ON timestamp: {}".
                           format(bts_power_on_timestamp), log_hierarchy=3)
        self._kpi_params['kpi3']['start_point_timestamp'] = bts_power_on_timestamp


class BBMODResetRunnerTemplate(object):
    TEMP_ALLOWED_ALARMS = []

    def __init__(self, bbmod_id="random", **kwargs):
        super(BBMODResetRunnerTemplate, self).__init__(operation_description='BBMOD Reset', kpi_names=['kpi5'],
                                                       **kwargs)
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 30
        self._all_bbmod_ids = convert_to_robot_kw(self._get_all_supported_bbmod_ids)
        self._bbmod_id = bbmod_id

    def run_operation(self):
        bbmod_id = convert_to_robot_kw(self._get_bbmod_id)
        self.custom_logger(log_info_to_console, msg="Reset BBMOD-{}".format(bbmod_id), log_hierarchy=2)
        convert_to_robot_kw(self.bbu.reset_bbmod, bts_id=self.bts_id, du_id=self.du_id, bbmod_id=bbmod_id)

    def _get_all_supported_bbmod_ids(self):
        try:
            convert_to_robot_kw(self.bbu.connect, bts_id=self.bts_id, du_id=self.du_id)
            bbmod_ids = convert_to_robot_kw(self.bbu._get_all_bbmod_ids, bts_id=self.bts_id, du_id=self.du_id)
            bbmods_handling_gsm_or_wcdma_cells = convert_to_robot_kw(self._get_bbmods_handling_gsm_or_wcdma_cells,
                                                                     bts_id=self.bts_id, du_id=self.du_id)
            return list(set(bbmod_ids) - set(bbmods_handling_gsm_or_wcdma_cells))
        finally:
            convert_to_robot_kw(self.bbu.disconnect, bts_id=self.bts_id, du_id=self.du_id)

    def _get_bbmod_id(self):
        if self._bbmod_id == 'random':
            bbmod_id = random.choice(self._all_bbmod_ids)
        else:
            bbmod_id = int(self._bbmod_id)

        return bbmod_id

    def _get_bbmods_handling_gsm_or_wcdma_cells(self, bts_id, du_id):
        bbmod_cell_mapping = convert_to_robot_kw(self.cell.get_bbmod_cell_mapping,
                                                 bts_id=bts_id, du_id=du_id)
        bbmod_ids_map = convert_to_robot_kw(self.bbu.get_all_bbmod_ids_map,
                                            bts_id=bts_id, du_id=du_id)
        bbmod_ids = []
        for bbmod in bbmod_cell_mapping:
            for cell_id in bbmod_cell_mapping[bbmod]:
                if self.cell.is_gsm_cell(cell_id) or self.cell.is_wcdma_cell(cell_id):
                    runtime_id = bbmod_ids_map.get(bbmod).split('-')[-1]
                    bbmod_ids.append(int(runtime_id))
                    continue
        return bbmod_ids


class RMODResetCommon(ABC):
    TEMP_ALLOWED_ALARMS = [{'fault_name': 'No connection to unit',
                            'fault_id': 10,
                            'alarm_id': 7116}]

    def __init__(self, ru_id, operation_description, kpi_names, **kwargs):
        # TODO if it will be necessary it's possible add additional mode:
        # 'mix' - all/random after second iteration

        super(RMODResetCommon, self).__init__(operation_description=operation_description,
                                              kpi_names=kpi_names,
                                              **kwargs)
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 60
        self._confirmation_delay = 5
        self._all_ru_ids = convert_to_robot_kw(self._get_all_ru_ids)
        self._ru_id = ru_id
        if self._add_default_faults:
            self.temp_allowed_alarms.extend(convert_to_robot_kw(self._generate_additional_temp_allowed_alarms))

    @abstractmethod
    def run_operation(self):
        pass

    def _get_all_ru_ids(self):
        try:
            convert_to_robot_kw(self.ru.connect, bts_id=self.bts_id, du_id=self.du_id)
            return convert_to_robot_kw(self.ru._get_all_radio_ids, bts_id=self.bts_id, du_id=self.du_id,
                                       radio_type='rmod')['rmod']
        finally:
            convert_to_robot_kw(self.ru.disconnect, bts_id=self.bts_id, du_id=self.du_id)

    def _get_ru_id(self):
        if self._ru_id == 'random':
            ru_id = random.choice(self._all_ru_ids)
        elif self._ru_id == 'all':
            ru_id = None
        else:
            ru_id = int(self._ru_id)

        return ru_id

    def _generate_additional_temp_allowed_alarms(self):
        bts_info = convert_to_robot_kw(self.bbu.get_bts_info, bts_id=self.bts_id, du_id=self.du_id)
        shared_cells = convert_to_robot_kw(self.cell.get_cells_shared_on_more_than_one_ru, bts_id=self.bts_id,
                                           du_id=self.du_id)
        temp_alarms = []
        for shared_cell in shared_cells:
            unit_path = f"[{bts_info['name']}] {shared_cell}"
            temp_alarms.append(
                {
                    'fault_name': 'Transmission path failure',
                    'fault_id': 4003,
                    'alarm_id': 7115,
                    'unit_path': unit_path
                }
            )

        extensions = self.ru.get_all_extension_dist_names(bts_id=self.bts_id, du_id=self.du_id)
        for extension in extensions:
            unit_path = f"[{bts_info['name']}] {extension}"
            temp_alarms.append(
                {
                    'fault_name': 'No connection to unit',
                    'fault_id': 10,
                    'alarm_id': 7115,
                    'unit_path': unit_path
                }
            )

        return temp_alarms


class RMODResetRunnerTemplate(RMODResetCommon):

    def __init__(self, ru_id="random", **kwargs):
        # TODO if it will be necessary it's possible add additional mode:
        # 'mix' - all/random after second iteration

        super(RMODResetRunnerTemplate, self).__init__(ru_id=ru_id,
                                                      operation_description='RMOD Reset',
                                                      kpi_names=['kpi51a', 'kpi51b'],
                                                      **kwargs)

    def run_operation(self):
        ru_id = convert_to_robot_kw(self._get_ru_id)
        self.custom_logger(log_info_to_console, msg="Reset RU{}".format(ru_id if ru_id is not None else 's'),
                           log_hierarchy=2)
        if ru_id is None:
            convert_to_robot_kw(self.ru.reset_all_radio_unit, bts_id=self.bts_id, du_id=self.du_id, timeout=600,
                                force_radio_reset=True)
        else:
            convert_to_robot_kw(self.ru.reset_radio_unit, bts_id=self.bts_id, du_id=self.du_id, radio_unit_id=ru_id,
                                timeout=600, force_radio_reset=True)


class RMODPowerResetRunnerTemplate(RMODResetCommon):
    TEMP_ALLOWED_ALARMS = [{'fault_name': 'No connection to unit',
                            'fault_id': 10,
                            'alarm_id': 7116},
                           {'fault_name': 'Unit power reset',
                            'fault_id': 4589,
                            'alarm_id': 7115},
                           {'fault_name': 'Not able to synchronize baseband bus',
                            'fault_id': 1815,
                            'alarm_id': 7116}]

    def __init__(self, ru_id="all", **kwargs):
        """
        :param ru_id:   'all' - all RUs are reset,
                        'random' - random RU is reset,
                        int - specific RU is reset(based on tl config)
        """
        super(RMODPowerResetRunnerTemplate, self).__init__(ru_id=ru_id,
                                                           operation_description='Power Radio Unit Reset',
                                                           kpi_names=['kpi54a'],
                                                           **kwargs)

        self._delay_after_power_on = 10
        self.delay_for_checking_allowed_alarms = self.delay_for_checking_allowed_alarms or 15
        self._confirmation_delay = self._confirmation_delay + self._delay_after_power_on
        self.custom_logger(log_info_to_console, msg=f"confirmation delay = {self._confirmation_delay}", log_hierarchy=2)
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 2 * 60
        self._kpi_params['kpi54a'] = {}
        self._kpi_params['kpi54b'] = {}

    def _get_all_ru_ids(self):
        try:
            convert_to_robot_kw(self.ru.connect, bts_id=self.bts_id, du_id=self.du_id)
            rus_info = convert_to_robot_kw(self.ru._get_all_rus_info, bts_id=self.bts_id, du_id=self.du_id,
                                           radio_type='rmod')
        finally:
            convert_to_robot_kw(self.ru.disconnect, bts_id=self.bts_id, du_id=self.du_id)

        tl_config_rmod_ids = []
        number_of_radios = convert_to_robot_kw(self.ru.get_count_of_radios, bts_id=self.bts_id, du_id=self.du_id)
        for ru_info in rus_info:
            for ru_id, tl_ru_config in enumerate(range(number_of_radios)):
                tl_config_serial_number = tl_config.get_radio_serial_number(bts_id=self.bts_id, du_id=self.du_id,
                                                                            ru_id=ru_id)
                if tl_config_serial_number == ru_info['serialNumber']:
                    tl_config_rmod_ids.append(ru_id)
                    break
        tl_config_rmod_ids.sort()
        return tl_config_rmod_ids

    def _verify_radio_unit_is_offline(self, ru_id):
        ru_configuration_id = convert_to_robot_kw(self.ru.get_radio_unit_configuration_based_on_tl_config_id,
                                                  ru_id=ru_id)['configuration_id']
        try:
            convert_to_robot_kw(self.ru.wait_for_radio_unit_statuses, bts_id=self.bts_id, du_id=self.du_id,
                                ru_id=ru_configuration_id, radio_type='rmod', availability_status='notinstalled',
                                timeout=120)
        except IncorrectStatuses:
            raise UnexpectedRMODStatus(f"RMOD-{ru_configuration_id} availability status"
                                       " is not offline after power off."
                                       " Perhaps you have wrong defined PDU port to RMOD"
                                       " (or even PDU address) in configuration init.py")

    def run_operation(self):
        self.custom_logger(log_info_to_console, msg="Start power reset", log_hierarchy=2)
        ru_id = convert_to_robot_kw(self._get_ru_id)    # if None all RUs are reset
        ru_id_to_print = ru_id if ru_id is not None else 's'
        self.custom_logger(log_info_to_console, msg=f"RU{ru_id_to_print} Power OFF", log_hierarchy=2)
        convert_to_robot_kw(self.ru.power_reset_radio_unit, bts_id=self.bts_id, du_id=self.du_id, radio_unit_id=ru_id)
        convert_to_robot_kw(self._verify_radio_unit_is_offline, ru_id=ru_id)
        self.custom_logger(log_info_to_console, msg=f"RU{ru_id_to_print} Power ON", log_hierarchy=2)
        bts_power_on_timestamp = datetime.datetime.now(pytz.utc) - datetime.timedelta(seconds=self._confirmation_delay)
        self.custom_logger(log_info_to_console, msg="RU{} Power ON timestamp: {}".
                           format(ru_id_to_print, bts_power_on_timestamp), log_hierarchy=3)
        self._kpi_params['kpi54a']['start_point_timestamp'] = bts_power_on_timestamp
        self._kpi_params['kpi54b']['start_point_timestamp'] = bts_power_on_timestamp


