class ASIRMODResetViaASiRCliRunnerTemplate(object):
    TEMP_ALLOWED_ALARMS = [{'fault_name': 'Failure detected on assigned antennas',
                            'fault_id': 4479}]

    def __init__(self, hub_id="random", hubs_sns=[], **kwargs):

        super(ASIRMODResetViaASiRCliRunnerTemplate, self).__init__(operation_description='ASIRMOD Reset',
                                                                   kpi_names=['kpi41'], **kwargs)

        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 60
        if hubs_sns:
            self._all_asir_ids = convert_to_robot_kw(self._get_hub_ids_from_hub_sns, hubs_sns=hubs_sns)
        else:
            self._all_asir_ids = convert_to_robot_kw(self.asir.get_all_hub_ids, bts_id=self.bts_id)
        self._hub_id = hub_id
        log_info_to_console("Available HUB IDs: {}".format(str(self._all_asir_ids)), log_hierarchy=2)

    def run_operation(self):
        hub_id = convert_to_robot_kw(self._get_hub_id)
        self.custom_logger(log_info_to_console, msg="Reset HUB{}".format(hub_id), log_hierarchy=2)
        convert_to_robot_kw(self.asir.reset_hub, bts_id=self.bts_id, hub_id=hub_id, timeout=0)  # timeout=0 means
        # don't wait for results

    def _get_hub_ids_from_hub_sns(self, hubs_sns):
        hub_ids = []
        hubs_info = convert_to_robot_kw(self.asir.get_all_hubs_with_cell_and_antenna_mapping, bts_id=self.bts_id)
        for hub_sn in hubs_sns:
            hub_ids.append(hubs_info[hub_sn]["id"])
        return hub_ids

    def _get_hub_id(self):
        if self._hub_id == 'random':
            hub_id = random.choice(self._all_asir_ids)
        else:
            hub_id = int(self._hub_id)

        return hub_id


class ASIRANTResetRunnerTemplate(object):
    TEMP_ALLOWED_ALARMS = [{'fault_name': 'Failure detected on assigned antennas',
                            'fault_id': 4479}]

    # for NRCELL 'alarm_id': 7114,
    # for LNCEL 'alarm_id': 7654,

    def __init__(self, ant_id="random", related_asirmod_sns=[], **kwargs):

        super(ASIRANTResetRunnerTemplate, self).__init__(operation_description='ANT Reset', kpi_names=['kpi42'],
                                                         **kwargs)

        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 30
        self.delay_for_checking_allowed_alarms = self.delay_for_checking_allowed_alarms or 5

        self.asirmod_sns = related_asirmod_sns
        self._all_ant_ids = convert_to_robot_kw(self._get_antenna_ids)
        self._ant_id = ant_id
        self._initial_calculate_kpi_value = self.calculate_kpi
        self.custom_logger(log_info_to_console, msg="Available ANT IDs: {}".format(str(self._all_ant_ids)),
                           log_hierarchy=2)

    def run_operation(self):
        self.calculate_kpi = self._initial_calculate_kpi_value
        ant_id = convert_to_robot_kw(self._get_ant_id)
        self.custom_logger(log_info_to_console, msg="Reset ANTMOD-{}".format(ant_id), log_hierarchy=2)
        if not self._are_all_related_cells_mapped_with_more_than_one_antmod(ant_id):
            if 'kpi42' in self.kpi_names and self.calculate_kpi:
                logging.info("KPI42 cannot be measured for ANTMOD-{} due to cell having only one ANTMOD. "
                             "KPIs will not be calculated".format(ant_id))
                self.calculate_kpi = False
        convert_to_robot_kw(self.asir.reset_antenna, bts_id=self.bts_id, ant_id=ant_id, timeout=0)  # timeout=0 means
        # don't wait for results

    def _get_ant_id(self):
        if self._ant_id == 'random':
            ant_id = random.choice(self._all_ant_ids)
        elif isinstance(self._ant_id, list):
            random.choice(self._ant_id)
        else:
            ant_id = int(self._ant_id)

        return ant_id

    def _get_antenna_ids(self):
        if self.asirmod_sns:
            antennas_ids = convert_to_robot_kw(self._get_antenna_ids_from_asirmod_mapping)
        else:
            antennas_ids = convert_to_robot_kw(self._get_antenna_ids_from_cells_mapping)
        return list(set(antennas_ids))

    def _get_antenna_ids_from_asirmod_mapping(self):
        asirmods_info = convert_to_robot_kw(self.asir.get_all_hubs_with_cell_and_antenna_mapping, bts_id=self.bts_id)
        antennas_ids = []
        for asirmod_sn in self.asirmod_sns:
            antennas_related_to_hub = [antenna_name.split("-")[-1]
                                       for antenna_name in list(asirmods_info[asirmod_sn]["antennas"])]
            antennas_ids.extend(antennas_related_to_hub)
        return antennas_ids

    def _get_antenna_ids_from_cells_mapping(self):
        cell_antenna_map = convert_to_robot_kw(self.asir.get_all_cells_with_antenna_mapping, bts_id=self.bts_id)
        antennas_ids = [antenna["id"] for cell in cell_antenna_map for antenna in cell["antennas"]]
        return list(set(antennas_ids))

    def _are_all_related_cells_mapped_with_more_than_one_antmod(self, ant_id):
        cell_antenna_mapping = convert_to_robot_kw(self.asir.get_all_cells_with_antenna_mapping, bts_id=self.bts_id)
        min_antmods = 2
        for cell in cell_antenna_mapping:
            for antenna in cell['antennas']:
                if antenna['id'] == int(ant_id) and len(cell['antennas']) < min_antmods:
                    return False
        return True


class CellOperationRunnerTemplateBase(object):
    def __init__(self, operation_description, kpi_names, cell_id="random", super_cell=False, related_asirmod_sns=[],
                 additional_allowed_alarms=[], **kwargs):
        super(CellOperationRunnerTemplateBase, self).__init__(operation_description=operation_description,
                                                              kpi_names=kpi_names,
                                                              additional_allowed_alarms=additional_allowed_alarms,
                                                              **kwargs)
        if related_asirmod_sns:
            self._all_cell_ids = convert_to_robot_kw(self._get_cell_ids_related_to_asirmods,
                                                     asirmod_sns=related_asirmod_sns)
        elif super_cell is True:
            self._all_cell_ids = convert_to_robot_kw(self.cell.get_super_cell_ids, bts_id=self.bts_id,
                                                     du_id=self.du_id)
        else:
            cell_type = convert_to_robot_kw(self._get_supported_rats)
            self._all_cell_ids = convert_to_robot_kw(self._get_all_cells_ids, cell_type=cell_type)
        self._cell_id = cell_id
        self.custom_logger(log_info_to_console, msg="Available CELL IDs: {}".
                           format(str(self._all_cell_ids)), log_hierarchy=2)

    def _get_cell_ids_related_to_asirmods(self, asirmod_sns):
        asirmods_info = convert_to_robot_kw(self.asir.get_all_hubs_with_cell_and_antenna_mapping,
                                            bts_id=self.bts_id)
        cells_ids = []
        for asirmod_sn in asirmod_sns:
            cells_related_to_hub = [cell_name.split(".")[-1] for cell_name in
                                    list(asirmods_info[asirmod_sn]["cells"])]
            cells_ids.extend(cells_related_to_hub)
        return list(set(cells_ids))

    def _get_all_cells_ids(self, cell_type):
        try:
            convert_to_robot_kw(self.cell.connect, bts_id=self.bts_id, du_id=self.du_id)
            return convert_to_robot_kw(self.cell._get_all_global_cell_ids, cell_type=cell_type,
                                       bts_id=self.bts_id, du_id=self.du_id)
        finally:
            convert_to_robot_kw(self.cell.disconnect, bts_id=self.bts_id, du_id=self.du_id)

    def _get_cell_id(self):
        if self._cell_id == 'random':
            cell_id = random.choice(self._all_cell_ids)
        else:
            cell_id = int(self._cell_id)

        return cell_id

    def _get_supported_rats(self):
        return ["nr", "lte", "wcdma", "gsm"]


class CellBlockUnblockRunnerTemplate(CellOperationRunnerTemplateBase):
    BLOCK_FAULT_ID = 49
    ALLOWED_ALARMS = [{'fault_name': 'Cell blocked',
                       'fault_id': 49,
                       'severity': 'Critical'}]

    # for NRCELL 'alarm_id': 7102,
    # for LNCEL 'alarm_id': 7653,

    def __init__(self, cell_id="random", super_cell=False, related_asirmod_sns=[], additional_allowed_alarms=[],
                 **kwargs):
        additional_allowed_alarms.extend(self.ALLOWED_ALARMS)
        super(CellBlockUnblockRunnerTemplate, self).__init__(cell_id=cell_id, super_cell=super_cell,
                                                             related_asirmod_sns=related_asirmod_sns,
                                                             operation_description='Block/Unblock',
                                                             kpi_names=['kpi17a', 'kpi17b'],
                                                             additional_allowed_alarms=additional_allowed_alarms,
                                                             **kwargs)

    def run_operation(self):
        cell_id = convert_to_robot_kw(self._get_cell_id)
        self.custom_logger(log_info_to_console, msg='Block cell {}'.format(cell_id), log_hierarchy=2)
        convert_to_robot_kw(self.cell.block_cell, bts_id=self.bts_id, du_id=self.du_id, cell_id=cell_id)
        self.custom_logger(log_info_to_console, msg="Wait for 'Cell blocked' alarm activation",
                           log_hierarchy=2)
        convert_to_robot_kw(self.alarm.wait_for_alarm_activation,
                            fault_id=CellBlockUnblockRunnerTemplate.BLOCK_FAULT_ID,
                            bts_id=self.bts_id, du_id=self.du_id)
        self.custom_logger(log_info_to_console, msg="Cell BLOCKED alarm appeared", log_hierarchy=2)
        self.custom_logger(log_info_to_console, msg='Unblock cell {}'.format(cell_id), log_hierarchy=2)
        convert_to_robot_kw(self.cell.unblock_cell, bts_id=self.bts_id, cell_id=cell_id, du_id=self.du_id)
        self.custom_logger(log_info_to_console, msg="Wait for 'Cell blocked' alarm deactivation",
                           log_hierarchy=2)
        convert_to_robot_kw(self.alarm.wait_for_alarm_deactivation,
                            fault_id=CellBlockUnblockRunnerTemplate.BLOCK_FAULT_ID,
                            bts_id=self.bts_id, du_id=self.du_id)
        self.custom_logger(log_info_to_console, msg="Cell UNBLOCKED alarm disappeared", log_hierarchy=2)


class SwUpgradeRunnerTemplate(object):
    TEMP_ALLOWED_ALARMS = [{'fault_name': 'No X2 link available',
                            'alarm_id': 7107,
                            'fault_id': 7300,
                            'severity': 'Major'}]

    def __init__(self, sw_version, target_dir, kpi_names=['kpi2b', 'kpi2d'],
                 check_passive=False, **kwargs):
        self.TEMP_ALLOWED_ALARMS.extend(SiteResetCommons.TEMP_ALLOWED_ALARMS)
        super(SwUpgradeRunnerTemplate, self).__init__(operation_description='Software Upgrade', kpi_names=kpi_names,
                                                      **kwargs)
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 3 * 60
        self.gnb = GnbSwUpdate()
        self.sw_version = sw_version
        self.target_dir = target_dir
        self._check_passive_sw = check_passive

    def checks_before_operation(self, **kwargs):
        super(SwUpgradeRunnerTemplate, self).checks_before_operation(**kwargs)
        if self._check_passive_sw and self.sw_version is not None:
            if convert_to_robot_kw(self.bbu.check_bts_sw_version, sw_version=self.sw_version, partition="passive",
                                   bts_id=self.bts_id, du_id=self.du_id) is True:
                raise Exception("Passive SW and target SW are the same: {} on GNB{}_DU{}".
                                format(self.sw_version, self.bts_id, self.du_id))

    def checks_after_operation(self, **kwargs):
        super(SwUpgradeRunnerTemplate, self).checks_after_operation(**kwargs)
        if self.sw_version is not None:
            if convert_to_robot_kw(self.bbu.check_bts_sw_version, sw_version=self.sw_version, partition="active",
                                   bts_id=self.bts_id, du_id=self.du_id) is False:
                raise Exception("BTS GNB{}_DU{} version not changed, target build: {}".
                                format(self.bts_id, self.du_id, self.sw_version))

    def run_operation(self):
        pkg_path = convert_to_robot_kw(self.gnb.download_sw_package, sw_version=self.sw_version, target_dir=self.target_dir)
        self.custom_logger(log_info_to_console, msg="Software upgrade. Package path {}".format(pkg_path),
                           log_hierarchy=2)
        convert_to_robot_kw(self.gnb.update_software, sw_package_dir=pkg_path, timeout=3600, bts_id=self.bts_id,
                            du_id=self.du_id)


