class ApiPowerResetRunnerTemplate(SiteResetCommons):

    def __init__(self, **kwargs):
        super(ApiPowerResetRunnerTemplate, self).__init__(operation_description='Power Site Reset via ADMIN API',
                                                          kpi_names=['kpi3'], **kwargs)

        self._confirmation_delay = 5
        self.delay_for_checking_onAir = self.delay_for_checking_onAir or 2 * 60
        self._kpi_params['kpi3'] = {}

    def run_operation(self):
        self.custom_logger(log_info_to_console, msg="BTS Power Reset via ADMIN API", log_hierarchy=2)
        convert_to_robot_kw(self.bbu.power_reset_bts, bts_id=self.bts_id, du_id=self.du_id)
        bts_power_reset_timestamp = datetime.datetime.now(pytz.utc) - datetime.timedelta(seconds=self._confirmation_delay)
        self.custom_logger(log_info_to_console, msg="BTS Power Reset timestamp: {}".
                           format(bts_power_reset_timestamp), log_hierarchy=3)
        self._kpi_params['kpi3']['start_point_timestamp'] = bts_power_reset_timestamp
